import ee
ee.Initialize(project='earthsense-436113')

def get_collection_and_note(year, geom):
    note = ""
    if year == 2021:
        col8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate('2021-01-01', '2021-12-31').filterBounds(geom)
        col9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate('2021-11-01', '2021-12-31').filterBounds(geom)
        col = col8.merge(col9)
        if col.size().getInfo() == 0:
            note = "No L8/L9; widened to 2020-07–2022-06."
            col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate('2020-07-01', '2022-06-30').filterBounds(geom) \
                .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate('2021-11-01', '2022-06-30').filterBounds(geom))
        return col, note
    else:
        col5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterDate(f'{year}-01-01', f'{year}-12-31').filterBounds(geom)
        if col5.size().getInfo() == 0:
            col4 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2').filterDate(f'{year}-01-01', f'{year}-12-31').filterBounds(geom)
            if col4.size().getInfo() == 0:
                note = "No LT05/LT04; widened to 1983–1985."
                col = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterDate('1983-01-01', '1985-12-31').filterBounds(geom) \
                    .merge(ee.ImageCollection('LANDSAT/LT04/C02/T1_L2').filterDate('1983-01-01', '1985-12-31').filterBounds(geom))
                return col, note
            else:
                note = "Using LT04 fallback."
                return col4, note
        return col5, note

def mask_scale_ndvi(img):
    qa = img.select('QA_PIXEL')
    radsat = img.select('QA_RADSAT')
    mask = qa.bitwiseAnd(1 << 1).eq(0) \
        .And(qa.bitwiseAnd(1 << 2).eq(0)) \
        .And(qa.bitwiseAnd(1 << 3).eq(0)) \
        .And(qa.bitwiseAnd(1 << 4).eq(0)) \
        .And(qa.bitwiseAnd(1 << 5).eq(0)) \
        .And(radsat.eq(0))
    scaled = img.select('SR_B.*').multiply(0.0000275).add(-0.2).updateMask(mask)
    ndvi_l89 = scaled.normalizedDifference(['SR_B5', 'SR_B4'])
    ndvi_l45 = scaled.normalizedDifference(['SR_B4', 'SR_B3'])
    sc = ee.String(img.get('SPACECRAFT_ID'))
    is8 = sc.compareTo('LANDSAT_8').eq(0)
    is9 = sc.compareTo('LANDSAT_9').eq(0)
    ndvi = ee.Image(ee.Algorithms.If(is8.Or(is9), ndvi_l89, ndvi_l45)).rename('ndvi')
    return ndvi.copyProperties(img, img.propertyNames())

def year_stats(year, geom):
    col, note = get_collection_and_note(year, geom)
    size = col.size().getInfo()
    if size == 0:
        return {'status': 'C1', 'note': 'Empty collection after all fallbacks.'}
    ndvi_col = col.map(mask_scale_ndvi).select('ndvi')
    ndvi_p75 = ndvi_col.reduce(ee.Reducer.percentile([75])).select(['ndvi_p75'], ['ndvi'])
    scale_m = 1000
    total_px = ee.Image.constant(1).rename('one').clip(geom).reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale_m, maxPixels=1e9).get('one').getInfo()
    valid_px = ndvi_p75.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=scale_m, maxPixels=1e9).get('ndvi').getInfo()
    if total_px is None or valid_px is None:
        return {'status': 'C3', 'note': 'Count retrieval failed.'}
    if int(valid_px) == 0:
        return {'status': 'C2', 'note': 'No valid pixels after masking.'}
    veg = ndvi_p75.gt(0.3).rename('veg').updateMask(ndvi_p75.mask())
    veg_px = veg.reduceRegion(
        reducer=ee.Reducer.sum(), geometry=geom, scale=scale_m, maxPixels=1e9).get('veg').getInfo()
    if veg_px is None:
        return {'status': 'C3', 'note': 'Veg sum failed.'}
    veg_frac = float(veg_px) / float(valid_px)
    cloud_frac = max(0.0, 1.0 - float(valid_px) / float(total_px))
    if not (0.0 <= veg_frac <= 1.0):
        return {'status': 'C3', 'note': 'Invalid fraction.'}
    return {'status': 'OK', 'images': int(size), 'note': note,
            'valid_px': int(valid_px), 'veg_px': int(veg_px),
            'veg_frac': veg_frac, 'cloud_frac': cloud_frac}

def main():
    try:
        geom = ee.Geometry.Rectangle([30.2, 31.3, 30.6, 31.6], proj=None, geodesic=False)
        y1, y2 = 1984, 2021
        s1 = year_stats(y1, geom)
        if s1.get('status') != 'OK':
            print(f"{y1} Status: {s1.get('status')}, Note: {s1.get('note')}")
            print(s1.get('status'))
            return
        s2 = year_stats(y2, geom)
        if s2.get('status') != 'OK':
            print(f"{y2} Status: {s2.get('status')}, Note: {s2.get('note')}")
            print(s2.get('status'))
            return
        print("Area: Rosetta Nile mouth | NDVI>0.3 on annual NDVI P75 | Scale=1000m")
        if s1.get('note'): print(f"{y1} Note: {s1.get('note')}")
        if s2.get('note'): print(f"{y2} Note: {s2.get('note')}")
        print(f"{y1} Images: {s1['images']}")
        print(f"{y2} Images: {s2['images']}")
        print(f"{y1} Valid px: {s1['valid_px']}, Veg px: {s1['veg_px']}, Veg%: {s1['veg_frac']*100:.1f}%, Masked%: {s1['cloud_frac']*100:.1f}%")
        print(f"{y2} Valid px: {s2['valid_px']}, Veg px: {s2['veg_px']}, Veg%: {s2['veg_frac']*100:.1f}%, Masked%: {s2['cloud_frac']*100:.1f}%")
        answer = "A" if s1['veg_frac'] > s2['veg_frac'] else "B"
        print(answer)
    except Exception as e:
        # For any API, collection, band, or memory error:
        print("D")

if __name__ == "__main__":
    main()
